import React, { useState, useEffect } from 'react';
import { 
  Home, List, BookOpen, Database, Menu, X, ChevronLeft, ChevronRight, ArrowRight, ChevronDown 
} from 'lucide-react';
import {
  XAxis, YAxis, CartesianGrid, ResponsiveContainer, LineChart, Line
} from 'recharts';
import { Link, useLocation } from 'react-router-dom';


// --- 型定義 ---
interface RankingItem {
  rank: number;
  title: string;
  isbn: string;
}

interface IssueData {
  issue: string;
  rankings: RankingItem[];
}

interface IssueInfo {
  id: number;
  issue_no: number;
  issue_label: string;
}

// --- モックデータ（複数の号を管理） ---
const allData: Record<string, IssueData> = {
  "2026年 第10号": {
    issue: "2026年 第10号",
    rankings: [
      { rank: 1, title: "ONE PIECE", isbn: "978-4-08-884013-0" },
      { rank: 2, title: "呪術廻戦", isbn: "978-4-08-883595-2" },
      { rank: 3, title: "僕のヒーローアカデミア", isbn: "978-4-08-883842-7" },
      { rank: 4, title: "サカモトデイズ", isbn: "978-4-08-884013-0" },
      { rank: 5, title: "アオのハコ", isbn: "978-4-08-883000-0" },
      { rank: 6, title: "夜桜さんちの大作戦", isbn: "978-4-08-883000-1" },
    ]
  },
  "2026年 第9号": {
    issue: "2026年 第9号",
    rankings: [
      { rank: 1, title: "呪術廻戦", isbn: "978-4-08-883595-2" },
      { rank: 2, title: "ONE PIECE", isbn: "978-4-08-884013-0" },
      { rank: 3, title: "サカモトデイズ", isbn: "978-4-08-884013-0" },
      { rank: 4, title: "僕のヒーローアカデミア", isbn: "978-4-08-883842-7" },
      { rank: 5, title: "アオのハコ", isbn: "978-4-08-883000-0" },
    ]
  }
};


const issueKeys = Object.keys(allData);

export default function IssueRanking() {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'all'>('home');
  // 号数の一覧（APIから取得）
  const [issueList, setIssueList] = useState<IssueInfo[]>([]);
  // 現在選択されている号のインデックス
  const [currentIssueIdx, setCurrentIssueIdx] = useState(0);
  // 現在選択されている号のランキングデータ
  const [currentRankings, setCurrentRankings] = useState<RankingItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const currentData = allData[issueKeys[currentIssueIdx]];

  const colors = {
    bg: '#0f172a',
    sidebar: '#1a2235',
    card: '#161d2f',
    accent: '#3b82f6',
    border: '#2d3748',
    textMuted: '#94a3b8',
    content: '#161d2f',
  };

  // 共通レイアウトスタイル
  const sidebarStyle: React.CSSProperties = {
    width: '240px',
    backgroundColor: colors.sidebar,
    position: 'fixed',
    height: '100vh',
    left: isSidebarOpen ? '0' : '-240px',
    transition: 'left 0.3s ease',
    zIndex: 90,
    paddingTop: '80px',
    borderRight: `1px solid ${colors.border}`,
    boxShadow: isSidebarOpen ? '10px 0 30px rgba(0,0,0,0.5)' : 'none'
  };

  const location = useLocation(); // 現在のパスを取得して「アクティブ状態」を判定する

  // 1. 初回マウント時に号数一覧を取得
  useEffect(() => {
    fetch("http://localhost:8080/issues")
      .then(res => res.json())
      .then((data: IssueInfo[]) => {
        // 新しい順（降順）に並べ替えてセット
        const sorted = data.sort((a, b) => b.id - a.id);
        setIssueList(sorted);
      })
      .catch(err => console.error("Issue fetch error:", err));
  }, []);

  console.log(issueList);


  // 号数を切り替える関数
  const changeIssue = (direction: 'next' | 'prev') => {
    if (direction === 'next' && currentIssueIdx > 0) {
      setCurrentIssueIdx(currentIssueIdx - 1);
    } else if (direction === 'prev' && currentIssueIdx < issueKeys.length - 1) {
      setCurrentIssueIdx(currentIssueIdx + 1);
    }
  };

  return (
    <div style={{ display: 'flex', backgroundColor: colors.bg, minHeight: '100vh', color: 'white', fontFamily: 'sans-serif' }}>

      {/* ハンバーガーメニュー */}
      <button onClick={() => setSidebarOpen(!isSidebarOpen)} style={{ position: 'fixed', top: '20px', left: '20px', zIndex: 100, backgroundColor: colors.sidebar, border: `1px solid ${colors.border}`, borderRadius: '4px', padding: '8px', cursor: 'pointer', color: 'white' }}>
        {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
      </button>


      {/* サイドバー（ドロワー形式） */}
          <aside style={sidebarStyle}>
          <div style={{ padding: '0 24px', marginBottom: '30px', fontSize: '18px', fontWeight: 'bold' }}>
            ジャンプ順位管理
          </div>
          <nav>
            {[
              { icon: <Home size={18}/>, label: "ホーム", path: "/jumprank", mode: 'home' as const },
              { icon: <List size={18}/>, label: "号別ランキング", path: "/jumprank/issue", mode: 'all' as const },
              { icon: <BookOpen size={18}/>, label: "作品一覧", path: "/jumprank/series", mode: 'all' as const },
              { icon: <Database size={18}/>, label: "データ管理", path: "/jumprank/series", mode: 'home' as const }
            ].map((item, i) => {
              // 現在のパスと一致しているか判定
              const isActive = location.pathname === item.path;

              return (
                <Link 
                  key={i} 
                  to={item.path}
                  // ページ遷移と同時にサイドバーを閉じる
                  onClick={() => setSidebarOpen(false)}
                  style={{ 
                    display: 'flex', 
                    alignItems: 'center', 
                    gap: '12px', 
                    padding: '15px 24px', 
                    cursor: 'pointer', 
                    textDecoration: 'none', // Link(a)タグの下線を消す
                    color: isActive ? colors.accent : 'white', 
                    backgroundColor: isActive ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
                    transition: 'background-color 0.2s',
                    borderLeft: isActive ? `4px solid ${colors.accent}` : '4px solid transparent',
                  }}
                  onMouseOver={(e) => e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.05)'}
                  onMouseOut={(e) => e.currentTarget.style.backgroundColor = isActive ? 'rgba(59, 130, 246, 0.1)' : 'transparent'}
                >
                  <span style={{ display: 'flex', alignItems: 'center' }}>
                    {item.icon}
                  </span>
                  <span style={{ fontSize: '14px', fontWeight: isActive ? 'bold' : 'normal' }}>
                    {item.label}
                  </span>
                </Link>
              );
            })}
          </nav>
        </aside>

            {/* オーバーレイ（サイドバーが開いている時に背景を暗くする） */}
            {isSidebarOpen && (
              <div 
                onClick={() => setSidebarOpen(false)}
                style={{
                  position: 'fixed',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  backgroundColor: 'rgba(0,0,0,0.5)',
                  zIndex: 80
                }}
              />
            )}

      {/* メインエリア */}
      <main style={{ flex: 1, padding: '80px 20px', maxWidth: '800px', margin: '0 auto' }}>

        {/* --- 号数切り替えセレクター (画像中央のUIを再現) --- */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '15px', marginBottom: '40px' }}>
          <button 
            onClick={() => changeIssue('prev')}
            disabled={currentIssueIdx === issueKeys.length - 1}
            style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer', opacity: currentIssueIdx === issueKeys.length - 1 ? 0.3 : 1 }}
          >
            <ChevronLeft size={32} />
          </button>

          <div style={{ position: 'relative', width: '280px' }}>
            <select 
              value={issueKeys[currentIssueIdx]}
              onChange={(e) => setCurrentIssueIdx(issueKeys.indexOf(e.target.value))}
              style={{
                width: '100%',
                padding: '12px 20px',
                backgroundColor: colors.card,
                color: 'white',
                border: `1px solid ${colors.border}`,
                borderRadius: '8px',
                fontSize: '18px',
                fontWeight: 'bold',
                appearance: 'none', // デフォルトの矢印を消す
                cursor: 'pointer',
                textAlign: 'center'
              }}
            >
              {issueKeys.map(key => <option key={key} value={key}>{key}</option>)}
            </select>
            <ChevronDown size={18} style={{ position: 'absolute', right: '15px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: colors.textMuted }} />
          </div>

          <button 
            onClick={() => changeIssue('next')}
            disabled={currentIssueIdx === 0}
            style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer', opacity: currentIssueIdx === 0 ? 0.3 : 1 }}
          >
            <ChevronRight size={32} />
          </button>
        </div>

        {/* --- コンテンツ表示 --- */}
        {viewMode === 'home' ? (
          <div style={{ backgroundColor: colors.card, borderRadius: '12px', padding: '24px', border: `1px solid ${colors.border}` }}>
            {currentData.rankings.slice(0, 5).map((item) => (
              <div key={item.rank} style={{ display: 'flex', alignItems: 'center', padding: '15px 0', borderBottom: `1px solid ${colors.border}` }}>
                <span style={{ fontSize: '20px', fontWeight: 'bold', width: '40px', fontStyle: 'italic' }}>{item.rank}位</span>
                <span style={{ fontSize: '18px' }}>{item.title}</span>
              </div>
            ))}
            <button onClick={() => setViewMode('all')} style={{ width: '100%', marginTop: '20px', padding: '14px', backgroundColor: '#252f48', border: 'none', borderRadius: '8px', color: 'white', cursor: 'pointer', fontWeight: 'bold' }}>
              全順位を表示
            </button>
          </div>
        ) : (
          <div style={{ backgroundColor: colors.card, borderRadius: '12px', border: `1px solid ${colors.border}`, overflow: 'hidden' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <tbody>
                {currentData.rankings.map((item) => (
                  <tr key={item.rank} style={{ borderBottom: `1px solid ${colors.border}` }}>
                    <td style={{ padding: '15px 20px', fontSize: '18px', fontWeight: 'bold', fontStyle: 'italic', width: '60px' }}>{item.rank}位</td>
                    <td style={{ padding: '15px 20px', fontSize: '16px' }}>{item.title}</td>
                    <td style={{ padding: '15px 20px', textAlign: 'right' }}>
                      <a href={`https://www.shueisha.co.jp/books/items/contents.html?isbn=${item.isbn}`} target="_blank" rel="noopener noreferrer" style={{ color: colors.accent, textDecoration: 'none', fontSize: '13px' }}>詳細 ↗</a>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>
    </div>
  );
}
